package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarUtils_parseOctal_TriageGen1Test {

    @Test
    public void testParseOctal_ValidSimple() {
        byte[] buffer = "000123 ".getBytes();
        // offset 0, length 7. End is 7. buffer[6] is ' ', so end becomes 6.
        // result should be 123 (octal) = 83 (decimal)
        assertEquals(83L, TarUtils.parseOctal(buffer, 0, 7));
    }

    @Test
    public void testParseOctal_ValidWithLeadingSpaces() {
        byte[] buffer = "   012 ".getBytes();
        // start moves to index 3. end is 6. trailer is ' '. end becomes 5.
        // result is 12 (octal) = 10 (decimal)
        assertEquals(10L, TarUtils.parseOctal(buffer, 0, 6));
    }

    @Test
    public void testParseOctal_ValidWithTrailingNUL() {
        byte[] buffer = "0755\0\0".getBytes();
        // length 6. end is 6. buffer[5] is 0. end becomes 5.
        // buffer[4] is 0. end becomes 4.
        // result 755 (octal) = 493 (decimal)
        assertEquals(493L, TarUtils.parseOctal(buffer, 0, 6));
    }

    @Test
    public void testParseOctal_ValidWithMixedTrailing() {
        byte[] buffer = "010 \0 ".getBytes();
        // length 6. end 6. buffer[5] is ' '. end 5. buffer[4] is 0. end 4.
        // result 10 (octal) = 8 (decimal)
        assertEquals(8L, TarUtils.parseOctal(buffer, 0, 6));
    }

    @Test
    public void testParseOctal_ZeroBufferStart() {
        byte[] buffer = new byte[]{0, 0, 0};
        assertEquals(0L, TarUtils.parseOctal(buffer, 0, 3));
    }

    @Test
    public void testParseOctal_LengthTooShort() {
        byte[] buffer = "1".getBytes();
        try {
            TarUtils.parseOctal(buffer, 0, 1);
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("must be at least 2"));
        }
    }

    @Test
    public void testParseOctal_InvalidTrailer() {
        byte[] buffer = "0123X".getBytes();
        // length 5. end 5. buffer[4] is 'X'. Not 0 or ' '.
        try {
            TarUtils.parseOctal(buffer, 0, 5);
            fail("Expected IllegalArgumentException due to invalid trailer");
        } catch (IllegalArgumentException e) {
            // Success
        }
    }

    @Test
    public void testParseOctal_InvalidDigit() {
        byte[] buffer = "0128 ".getBytes(); // '8' is not octal
        try {
            TarUtils.parseOctal(buffer, 0, 5);
            fail("Expected IllegalArgumentException due to invalid digit");
        } catch (IllegalArgumentException e) {
            // Success
        }
    }

    @Test
    public void testParseOctal_InvalidDigitNegative() {
        byte[] buffer = "01-3 ".getBytes();
        try {
            TarUtils.parseOctal(buffer, 0, 5);
            fail("Expected IllegalArgumentException due to invalid digit");
        } catch (IllegalArgumentException e) {
            // Success
        }
    }

    @Test
    public void testParseOctal_OffsetUsage() {
        byte[] buffer = "ABC012 \0".getBytes();
        // We want to parse starting from index 3
        // buffer[3] is '0'. length 5. end is 8.
        // buffer[7] is 0. end becomes 7.
        // result 12 (octal) = 10 (decimal)
        assertEquals(10L, TarUtils.parseOctal(buffer, 3, 5));
    }

    @Test
    public void testParseOctal_LargeOctal() {
        // Testing large value to ensure long handling
        // 777777777777777777 octal is very large
        byte[] buffer = "777777777777777777 ".getBytes();
        long expected = Long.parseLong("777777777777777777", 8);
        assertEquals(expected, TarUtils.parseOctal(buffer, 0, buffer.length));
    }
}
